import Foundation

final class Tally {
    var total: Decimal = 0
}

func totalOfAll(_ amounts: [Decimal]) async -> Decimal {
    let tally = Tally()
    await withTaskGroup(of: Void.self) { group in
        for amount in amounts {
            group.addTask { tally.total += amount }
        }
    }
    return tally.total
}
